import { useEffect, useState } from "react";
import { Line } from "react-chartjs-2";
import axios from "axios";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
} from "chart.js";

ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend
);

interface StockData {
  Date: string;
  Close: number;
  SMA5?: number;
  SMA25?: number;
  EMA12?: number;
  EMA26?: number;
  RSI14?: number;
  BB_UPPER?: number;
  BB_LOWER?: number;
}

// 銘柄選択
const STOCK_OPTIONS = [
  { label: "エヌビディア", value: "NVDA" },
  { label: "イオンキュー", value: "IONQ" },
  { label: "Tesla", value: "TSLA" }
];

export default function StockChart() {
  const [data, setData] = useState<StockData[]>([]);
  const [symbol, setSymbol] = useState("NVDA");
  const [loading, setLoading] = useState(false);

  const fetchData = async () => {
    setLoading(true);
    try {
      const response = await axios.post("http://127.0.0.1:8000/download_stock", { symbol });
      setData(response.data);
    } catch (error) {
      console.error(error);
      alert("データ取得に失敗しました");
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Chart.js用データ整形
  const chartData = {
    labels: data.map(d => d.Date),
    datasets: [
      {
        label: "終値",
        data: data.map(d => d.Close),
        borderColor: "rgba(75,192,192,1)",
        backgroundColor: "rgba(75,192,192,0.2)",
      },
      {
        label: "SMA5",
        data: data.map(d => d.SMA5),
        borderColor: "orange",
        borderDash: [5, 5],
      },
      {
        label: "SMA25",
        data: data.map(d => d.SMA25),
        borderColor: "purple",
        borderDash: [5, 5],
      },
      {
        label: "EMA12",
        data: data.map(d => d.EMA12),
        borderColor: "green",
        borderDash: [5, 2],
      },
      {
        label: "EMA26",
        data: data.map(d => d.EMA26),
        borderColor: "red",
        borderDash: [5, 2],
      },
      {
        label: "BB上限",
        data: data.map(d => d.BB_UPPER),
        borderColor: "blue",
        borderDash: [2, 2],
      },
      {
        label: "BB下限",
        data: data.map(d => d.BB_LOWER),
        borderColor: "blue",
        borderDash: [2, 2],
      }
    ]
  };

  return (
    <div>
      <form
        onSubmit={e => { e.preventDefault(); fetchData(); }}
        style={{ marginBottom: "20px" }}
      >
        <label>
          銘柄:
          <select value={symbol} onChange={e => setSymbol(e.target.value)}>
            {STOCK_OPTIONS.map(opt => (
              <option key={opt.value} value={opt.value}>
                {opt.label}
              </option>
            ))}
          </select>
        </label>
        <button type="submit" style={{ marginLeft: "10px" }}>
          {loading ? "読み込み中..." : "更新"}
        </button>
      </form>
      <Line data={chartData} />
    </div>
  );
}
